function Timeline_BeforeIntoTask3:__init()
    self.controller = nil

    self.OnTimelineStop = nil -- Action
    self.m_hasPlayed = false
end


function Timeline_BeforeIntoTask3:__delete()
end




function Timeline_BeforeIntoTask3:Start()
    KTool.SetActive(self.controller.gameObject, true)

    assert( self.playableDirector )

    -- 本 gameobj 务必绑定 collider
    local collider = KTool.GetComponent(self.controller.gameObject, typeof(Collider))
    assert( collider )


    assert( isNotNull( URPCameraController.Instance ) and isNotNull(  URPCameraController.Instance.mainCamera ) )
    local cBrain = KTool.GetComponent(URPCameraController.Instance.mainCamera.gameObject, typeof(CinemachineBrain))
    assert(cBrain)



    local timelineAsset = self.playableDirector.playableAsset
    ----

    local list = support.new_list(typeof(CS.UnityEngine.Timeline.TrackAsset))
    list:AddRange(timelineAsset:GetOutputTracks())

    for i = 0, list.Count - 1 do
        local track = list[i]
        if track.name == "targetCamera" then
            self.playableDirector:SetGenericBinding(track, cBrain)
        end
    end

    self.playableDirector:stopped( '+', function(playableDirector_)
        self:WhenStop(playableDirector_)
    end)
end




function Timeline_BeforeIntoTask3:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
    self:Delete()
end

-- =========================================== Self ================================================ --


function Timeline_BeforeIntoTask3:OnTriggerEnter(other)
    
    if other.CompareTag("Player") and not self.m_hasPlayed then
        self.m_hasPlayed = true
        print("进入timeline")
        self.playableDirector:Play()
    end
end


function Timeline_BeforeIntoTask3:WhenStop(playableDirector_)
    if self.OnTimelineStop ~= nil then
        self.OnTimelineStop()
    end
end






return Timeline_BeforeIntoTask3
